for reader in ['a','b']:
 data=json.loads((D/f'reader-{reader}.json').read_text());out=[]
 for a,b,c in zip(q,key,data['answers']):
  assert a['id']==b['id']==c['id'];grade,reason=findings[reader].get(a['id'],('correct','All requested material rulings match fixed key; summary evidence supports answer. Any additional unrequested caveat does not undo a resolved requested fact.'))
  out.append({'id':a['id'],'question':a['question'],'expected_answer':b['expected_answer'],'source_references':b['source_references'],'observed_answer':c['answer'],'reader_support':c['support'],'reader_evidence':c['evidence'],'grade':grade,'reason':reason,'unsupported_guess':False})
 res['readers'][reader]={'counts':{x:sum(v['grade']==x for v in out) for x in ['correct','partial','incorrect']},'grades':out}
